//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			Generator Data - DSE86xx
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2026-03-27		William Veim			Initial release (Based on "old function" - "HE_ParseGenerator_DSE86xx"
//	2.0.0				2025-04-17		William Veim			Rework - Moved modbus configuration to FB 
//
//===============================================================================================================================
//
//Example inline ST for alarm string (Out_GeneratorData.Alm_Active)
(*TON_ChangeString(PT:=T#5s);

IF Num_ActiveAlarms = 0 THEN
	Generators[0].Alm_Active :='No active alarms';
ELSIF TON_ChangeString.Q THEN
	index:=index+1;
	IF index >= Num_ActiveAlarms THEN
		index := 0;
	END_IF;
	TON_ChangeString.In := FALSE;
ELSE
	Generators[0].Alm_Active := Gen_ActiveAlarms[index];
	TON_ChangeString.In:=TRUE;
END_IF;*)
//
//===============================================================================================================================

 (*************************************************************************
 *	INITIALIZE VARIABELS
 *************************************************************************)

Ext_Generator_Data.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA

 (*************************************************************************
 *	CONGIURING MODBUS REQUEST
 *************************************************************************)
 
Inp_Request[Cfg_Request_StartPos+0].Enable :=TRUE;
Inp_Request[Cfg_Request_StartPos+0].NodeAdr := 1;
Inp_Request[Cfg_Request_StartPos+0].FunctionCode := eFun#Fn03_ReadHoldingRegisters;
Inp_Request[Cfg_Request_StartPos+0].Read.StartAddressLocal :=Cfg_HoldingReg_StartPos+0;
Inp_Request[Cfg_Request_StartPos+0].Read.StartAddressRemote := 3*256; // Page 3 – Generating Set Status Information
Inp_Request[Cfg_Request_StartPos+0].Read.Count := 7; 

Inp_Request[Cfg_Request_StartPos+1].Enable :=TRUE;
Inp_Request[Cfg_Request_StartPos+1].NodeAdr := 1;
Inp_Request[Cfg_Request_StartPos+1].FunctionCode := eFun#Fn03_ReadHoldingRegisters;
Inp_Request[Cfg_Request_StartPos+1].Read.StartAddressLocal :=Cfg_HoldingReg_StartPos+7;
Inp_Request[Cfg_Request_StartPos+1].Read.StartAddressRemote := 4*256; // Page 4 – Basic Instrumentation
Inp_Request[Cfg_Request_StartPos+1].Read.Count := 66; 

Inp_Request[Cfg_Request_StartPos+2].Enable :=TRUE;
Inp_Request[Cfg_Request_StartPos+2].NodeAdr := 1;
Inp_Request[Cfg_Request_StartPos+2].FunctionCode := eFun#Fn03_ReadHoldingRegisters;
Inp_Request[Cfg_Request_StartPos+2].Read.StartAddressLocal :=Cfg_HoldingReg_StartPos+73;
Inp_Request[Cfg_Request_StartPos+2].Read.StartAddressRemote := 7*256+6; // Page 7 – Accumulated Instrumentation
Inp_Request[Cfg_Request_StartPos+2].Read.Count := 12; 

Inp_Request[Cfg_Request_StartPos+3].Enable :=TRUE;
Inp_Request[Cfg_Request_StartPos+3].NodeAdr := 1;
Inp_Request[Cfg_Request_StartPos+3].FunctionCode := eFun#Fn03_ReadHoldingRegisters;
Inp_Request[Cfg_Request_StartPos+3].Read.StartAddressLocal :=Cfg_HoldingReg_StartPos+85;
Inp_Request[Cfg_Request_StartPos+3].Read.StartAddressRemote := 154*256; // Page 154 – Named Alarm Conditions
Inp_Request[Cfg_Request_StartPos+3].Read.Count := 38; 

Inp_Request[Cfg_Request_StartPos+4].Enable :=TRUE;
Inp_Request[Cfg_Request_StartPos+4].NodeAdr := 1;
Inp_Request[Cfg_Request_StartPos+4].FunctionCode := eFun#Fn03_ReadHoldingRegisters;
Inp_Request[Cfg_Request_StartPos+4].Read.StartAddressLocal :=Cfg_HoldingReg_StartPos+123;
Inp_Request[Cfg_Request_StartPos+4].Read.StartAddressRemote := 178*256+3; // Page 178 – Internal Analogue Sensor Readings and Unit Info
Inp_Request[Cfg_Request_StartPos+4].Read.Count := 1; 

(*************************************************************************
 *	UPDATING VARIABELS
 *************************************************************************)

//Communication state
IF (Inp_Request[Cfg_Request_StartPos+0].Status.Success AND NOT Inp_Request[Cfg_Request_StartPos+0].Status.Error) 
	AND (Inp_Request[Cfg_Request_StartPos+1].Status.Success AND NOT Inp_Request[Cfg_Request_StartPos+1].Status.Error) 
	AND (Inp_Request[Cfg_Request_StartPos+2].Status.Success AND NOT Inp_Request[Cfg_Request_StartPos+2].Status.Error) 
	AND (Inp_Request[Cfg_Request_StartPos+3].Status.Success AND NOT Inp_Request[Cfg_Request_StartPos+3].Status.Error)
	AND (Inp_Request[Cfg_Request_StartPos+4].Status.Success AND NOT Inp_Request[Cfg_Request_StartPos+4].Status.Error)THEN
	
	Wrk_CommState:=TRUE;
ELSE
	Wrk_CommState:=FALSE;
END_IF;

(*************************************************************************
 *	PARSING COMMON STATUS
 *************************************************************************)
//Page 3 (Register 3*256 = 768) - Generating Set Status Information - Read count 7 words

// Control Mode
CASE WORD_TO_UINT(Inp_HoldingRegister[Cfg_Page3_Offset + 4]) OF
	
	0: //STOP MODE
	Ext_Generator_Data.EXT_Operator.ControlMode:= 'Stop mode';
	
	1: //AUTO MODE
	Ext_Generator_Data.EXT_Operator.ControlMode:= 'Auto mode';
	
	2: //MANUAL MODE
	Ext_Generator_Data.EXT_Operator.ControlMode:= 'Manual mode';
	
	3: //TEST ON LOAD MODE
	Ext_Generator_Data.EXT_Operator.ControlMode:= 'Test on load mode';
	
	4: //AUTO WITH MANUAL RESTORE
	Ext_Generator_Data.EXT_Operator.ControlMode:= 'Auto with manual restore';
	
	5: //USER CONFIGURATION MODE
	Ext_Generator_Data.EXT_Operator.ControlMode:= 'User configuration mode';
	
	6: //TEST OFF LOAD MODE
	Ext_Generator_Data.EXT_Operator.ControlMode:= 'Test off load mode';
	
	7: //OFF MODE
	Ext_Generator_Data.EXT_Operator.ControlMode:= 'Off mode';
	
END_CASE;

(*************************************************************************
 *	PARSING GENERATOR DATA
*************************************************************************)
//Page 7 (Register 7*256+6 = 1798) - Accumulated Instrumentation - Read count 12 words
 
Ext_Generator_Data.EXT_Statistics.RunningHours:= 							REAL_TO_UDINT(HE_WORD_CheckValid(Word_1:=(Inp_HoldingRegister[Cfg_Page7_Offset + 0]), Word_2:=(Inp_HoldingRegister[Cfg_Page7_Offset + 1]), UnvalidValue:=16#FFFF));
Ext_Generator_Data.EXT_Statistics.Generator_PositiveEnergy:= 			HE_WORD_CheckValid(Word_1:=(Inp_HoldingRegister[Cfg_Page7_Offset + 2]), Word_2:=(Inp_HoldingRegister[Cfg_Page7_Offset + 3]), UnvalidValue:=16#FFFF) * REAL#0.1;
Ext_Generator_Data.EXT_Statistics.Generator_NegativeEnergy:= 		HE_WORD_CheckValid(Word_1:=(Inp_HoldingRegister[Cfg_Page7_Offset + 4]), Word_2:=(Inp_HoldingRegister[Cfg_Page7_Offset + 5]), UnvalidValue:=16#FFFF) * REAL#0.1;
 
(*************************************************************************
 *	PARSING ENGINE DATA
 *************************************************************************)
//Page 4 (Register 4*256 = 1024) - Basic Instrumentation - Read count 66 words
 
Ext_Generator_Data.EXT_Operator.Eng_OilPressure:= 						HE_WORD_CheckValid(Word_1:=(Inp_HoldingRegister[Cfg_Page4_Offset + 0]), Word_2:=0, UnvalidValue:=16#FFFF);
Ext_Generator_Data.EXT_Operator.Eng_OilTemperature:= 					HE_WORD_CheckValid(Word_1:=(Inp_HoldingRegister[Cfg_Page4_Offset + 2]), Word_2:=0, UnvalidValue:=16#FFFF);

// Alarms
Wrk_State[1]:=FALSE;
Wrk_Suffix[1]:='Communication lost';
Wrk_State[2]:=FALSE;
Wrk_Suffix[2]:='Shutdown active';
Wrk_State[3]:=FALSE;
Wrk_Suffix[3]:='Bypass bad';
Wrk_State[4]:=FALSE;
Wrk_Suffix[4]:='On bypass';
Wrk_State[5]:=FALSE;
Wrk_Suffix[5]:='Battery low';
Wrk_State[6]:=FALSE;
Wrk_Suffix[6]:='Alarm temperature';
Wrk_State[7]:=FALSE;
Wrk_Suffix[7]:='Alarm overload';
Wrk_State[8]:=FALSE;
Wrk_Suffix[8]:='UPS failiure';
Wrk_State[9]:=FALSE;
Wrk_Suffix[9]:='Communication lost internal';

(*************************************************************************
 *	EXCECUTING LOGIC BLOCK
 *************************************************************************)

FB_Data_Logic(Ext_Alarm:=Ext_Generator_Data.EXT_Alarm, 
						EXT_Engineering:=Ext_Generator_Data.EXT_Engineering, 
						Ext_General:=Ext_Generator_Data.EXT_General, 
						Int_Alarm:=Int_Alarm, 
						Inp_StateState:=Wrk_State, 
						Inp_StateSuffix:=Wrk_Suffix, 
						Inp_AlmSuppressDesc:=Cfg_AlmSuppressDesc, 
						Inp_AlmSuppress:=Inp_AlmSuppress);

(*************************************************************************
 *	UPDATING OUTPUTS
 *************************************************************************)
 
 //Block
 Sts_Alarm:=FB_Data_Logic.Sts_AlarmTriggered;
 
 //Structure
 Ext_Generator_Data.EXT_General.Connected_ControlCabinet:=Cfg_ConnCabinet;
 Ext_Generator_Data.EXT_General.Controlled_FromController:=Cfg_ControllerName;
 Ext_Generator_Data.EXT_General.Process_TAG:=Cfg_ProcessTAG;
